#!/usr/bin/env python3
"""Retire generated shared components made entirely of excluded system UI nodes."""

from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
from typing import Any


WIDGET_MARKER = "// GENERATED by iFF generate_canvas.py"
TEST_MARKER = "// GENERATED by iFF generate_shared_component_test.py"


def _inside(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False


def _read_prefix(path: Path, length: int = 160) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="strict")[:length]
    except (OSError, UnicodeError):
        return ""


def _atomic_write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.tmp")
    temporary.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    os.replace(temporary, path)


def _prune_missing_generated_asset_entries(pubspec: Path, project: Path, assets_root: Path) -> list[str]:
    if not pubspec.is_file():
        return []
    original = pubspec.read_text(encoding="utf-8")
    kept: list[str] = []
    removed: list[str] = []
    for line in original.splitlines(keepends=True):
        stripped = line.strip()
        if not stripped.startswith("- "):
            kept.append(line)
            continue
        value = stripped[2:].split("#", 1)[0].strip().strip("'\"")
        target = (project / value).resolve()
        if value.startswith("assets/iff_shared/") and _inside(target, assets_root) and not target.exists():
            removed.append(value)
            continue
        kept.append(line)
    if removed:
        temporary = pubspec.with_name(f".{pubspec.name}.tmp")
        temporary.write_text("".join(kept), encoding="utf-8")
        os.replace(temporary, pubspec)
    return removed


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--project-root", type=Path, required=True)
    parser.add_argument("--scene", type=Path, required=True)
    parser.add_argument("--registry", type=Path, required=True)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()

    project = args.project_root.resolve()
    scene_path = args.scene.resolve()
    registry_path = args.registry.resolve()
    output_path = args.out.resolve()
    for path, label in ((scene_path, "scene"), (registry_path, "registry"), (output_path, "report")):
        if not _inside(path, project):
            raise SystemExit(f"ERROR: {label} path escapes project root: {path}")

    scene = json.loads(scene_path.read_text(encoding="utf-8"))
    registry_exists = registry_path.is_file()
    registry = json.loads(registry_path.read_text(encoding="utf-8")) if registry_exists else {"components": {}}
    exclusions = scene.get("systemUiExclusions") or []
    excluded_nodes = {
        str(item.get("node"))
        for item in exclusions
        if isinstance(item, dict) and item.get("node") is not None
    }
    components = registry.get("components")
    if not isinstance(components, dict):
        raise SystemExit("ERROR: registry.components must be an object")

    removed_signatures: list[str] = []
    candidates: list[tuple[str, dict[str, Any]]] = []
    for signature, raw_entry in sorted(components.items()):
        if not isinstance(raw_entry, dict):
            continue
        source_value = raw_entry.get("source_spec_dir")
        if not isinstance(source_value, str) or not source_value:
            continue
        source_path = Path(source_value)
        if not source_path.is_absolute():
            source_path = project / source_path
        if source_path.resolve() != scene_path.parent.resolve():
            continue
        canonical = {str(item) for item in raw_entry.get("canonical_nodes") or []}
        if canonical and canonical <= excluded_nodes:
            candidates.append((str(signature), raw_entry))
            removed_signatures.append(str(signature))

    survivor_assets = {
        str(asset)
        for signature, entry in components.items()
        if str(signature) not in set(removed_signatures) and isinstance(entry, dict)
        for asset in entry.get("assets") or []
    }
    delete_paths: set[Path] = set()
    errors: list[str] = []
    widgets_root = project / "lib" / "shared" / "widgets"
    tests_root = project / "test" / "shared" / "widgets"
    assets_root = project / "assets" / "iff_shared"

    for signature, entry in candidates:
        widget_value = entry.get("widget_path")
        if not isinstance(widget_value, str) or not widget_value:
            errors.append(f"{signature}: missing widget_path")
            continue
        widget = (project / widget_value).resolve()
        if not _inside(widget, widgets_root):
            errors.append(f"{signature}: widget path is outside generated shared widget root")
            continue
        test = (tests_root / f"{widget.stem}_test.dart").resolve()
        expected = Path(f"{widget}.expected.json")
        if widget.exists() and WIDGET_MARKER not in _read_prefix(widget):
            errors.append(f"{signature}: refusing to delete non-generated widget {widget}")
        else:
            delete_paths.add(widget)
            delete_paths.add(expected)
        if test.exists() and TEST_MARKER not in _read_prefix(test):
            errors.append(f"{signature}: refusing to delete non-generated test {test}")
        else:
            delete_paths.add(test)
        for asset_value in entry.get("assets") or []:
            if str(asset_value) in survivor_assets:
                continue
            asset = (project / str(asset_value)).resolve()
            if not _inside(asset, assets_root):
                errors.append(f"{signature}: asset path is outside generated shared asset root")
            else:
                delete_paths.add(asset)

    report = {
        "ok": not errors,
        "applied": bool(args.apply and not errors),
        "excludedNodeCount": len(excluded_nodes),
        "removedSignatures": removed_signatures,
        "deletePaths": [str(path.relative_to(project)) for path in sorted(delete_paths)],
        "removedPubspecAssets": [],
        "errors": errors,
    }
    if errors:
        _atomic_write_json(output_path, report)
        raise SystemExit("ERROR: " + "; ".join(errors))

    if args.apply:
        for path in sorted(delete_paths, key=lambda item: len(item.parts), reverse=True):
            if path.is_file() or path.is_symlink():
                path.unlink()
        for signature in removed_signatures:
            components.pop(signature, None)
        if registry_exists or removed_signatures:
            _atomic_write_json(registry_path, registry)
        for path in sorted({item.parent for item in delete_paths}, key=lambda item: len(item.parts), reverse=True):
            current = path
            while _inside(current, assets_root) and current != assets_root:
                try:
                    current.rmdir()
                except OSError:
                    break
                current = current.parent
        report["removedPubspecAssets"] = _prune_missing_generated_asset_entries(
            project / "pubspec.yaml", project, assets_root
        )

    _atomic_write_json(output_path, report)
    print(json.dumps(report, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
